import{_ as a,o as r,c as t,a4 as i}from"./chunks/framework.CzJ_HCFe.js";const m=JSON.parse('{"title":"Deferred Funeral Rites (Pretakriya) Evidence Audit","description":"","frontmatter":{},"headers":[],"relativePath":"reference/37-cremation-evidence-audit.md","filePath":"reference/37-cremation-evidence-audit.md","lastUpdated":1788614098000}'),n={name:"reference/37-cremation-evidence-audit.md"};function o(d,e,s,h,l,c){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="deferred-funeral-rites-pretakriya-evidence-audit" tabindex="-1">Deferred Funeral Rites (Pretakriya) Evidence Audit <a class="header-anchor" href="#deferred-funeral-rites-pretakriya-evidence-audit" aria-label="Permalink to &quot;Deferred Funeral Rites (Pretakriya) Evidence Audit&quot;">​</a></h1><h2 id="verdict" tabindex="-1">Verdict <a class="header-anchor" href="#verdict" aria-label="Permalink to &quot;Verdict&quot;">​</a></h2><p>The <code>cremation</code> compatibility key is now deliberately narrowed to the source-verified election for <strong>deferred Pretakriya</strong>—rites that could not be performed at the time of death. It must not be used to postpone immediate Antyeshti.</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><ul><li><strong>MC-HINDI-IA</strong> — Rama Daivajna, <em>Muhurta Chintamani</em>, Nakshatra-prakarana, “Pretakriya ka muhurta,” verse 48, printed pp. 47-48; Internet Archive OCR lines 2956-2971.</li></ul><h2 id="implemented-admission" tabindex="-1">Implemented admission <a class="header-anchor" href="#implemented-admission" aria-label="Permalink to &quot;Implemented admission&quot;">​</a></h2><p>The verse and Hindi commentary admit deferred Pretakriya under exactly nine Nakshatras: Ashvini, Pushya, Hasta, Ashlesha, Moola, Jyeshtha, Shravana, Ardra and Swati. Automation applies this as a hard slot-time Nakshatra gate on Python, MCP and the browser.</p><h2 id="four-and-a-half-nakshatra-prohibition" tabindex="-1">Four-and-a-half-Nakshatra prohibition <a class="header-anchor" href="#four-and-a-half-nakshatra-prohibition" aria-label="Permalink to &quot;Four-and-a-half-Nakshatra prohibition&quot;">​</a></h2><p>The second half of the verse separately forbids cremation during latter-half Dhanishtha, Shatabhisha, Purva Bhadrapada, Uttara Bhadrapada and Revati. The shared Panchaka flag approximates this by marking all of Dhanishtha, but this approximation is not used as authority for the deferred-rite profile: none of the five restricted names enters the nine-star positive admission list.</p><h2 id="non-negotiable-boundary" tabindex="-1">Non-negotiable boundary <a class="header-anchor" href="#non-negotiable-boundary" aria-label="Permalink to &quot;Non-negotiable boundary&quot;">​</a></h2><p>Legal and medical requirements, prompt performance, family Sampradaya and the officiating priest take precedence over every result. The profile is capped for practitioner review and is not a generic “auspicious venture” ranking.</p>',11)])])}const p=a(n,[["render",o]]);export{m as __pageData,p as default};
